import { Sign, type SignProps, type SignShape } from "@/components/ui/sign"

// Generated by scripts/build-signs.mjs from a drawing made for 0nlyType.
const shape: SignShape = {"word":"next","line":[[["M",2.5,12],["L",17.5,12]],[["M",12.5,4],["L",20,11]],[["M",12.5,20],["L",20,13]]],"mirror":true}

/** The sign for "next": the word ruled in leaders along its strokes. */
function SignArrowRightDots(props: Omit<SignProps, "shape" | "variant">) {
  return <Sign shape={shape} variant="dots" {...props} />
}

export { SignArrowRightDots }
